"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import { ShoppingCart, Menu, X, PhoneCall, MessageCircle, PackageSearch, FileText } from "lucide-react";
import { useCartStore } from "@/lib/store/cart.store";
import CartDrawer from "../cart/CartDrawer";

export default function Navbar({ settings, topBanners = [] }: { settings?: any, topBanners?: string[] }) {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [cartOpen, setCartOpen] = useState(false);
  const [mounted, setMounted] = useState(false);
  const pathname = usePathname();
  
  const cartItemsCount = useCartStore((state) => state.getTotalItems());
  const [bannerIndex, setBannerIndex] = useState(0);
  const bannerMessages = topBanners && topBanners.length > 0 ? topBanners : ["Welcome to Sky Crackers Up to 90%", "Minimum Tamilnadu Order Rs 3,000", "Minimum Other State Orders 5,000"];

  useEffect(() => {
    const t = setTimeout(() => setMounted(true), 0);
    const bannerTimer = setInterval(() => {
      setBannerIndex((prev) => (prev + 1) % bannerMessages.length);
    }, 3000);
    
    
    const handleOpenCart = () => setCartOpen(true);
    window.addEventListener('open-cart-drawer', handleOpenCart);

    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener('open-cart-drawer', handleOpenCart);
      clearTimeout(t);
      clearInterval(bannerTimer);
    };
  }, [bannerMessages.length]);

  const navLinks = [
    { name: "Home", href: "/" },
    { name: "Shop", href: "/shop" },
    { name: "Order Tracking", href: "/track-order" },
    { name: "Payments", href: "/payments" },
    { name: "About Us", href: "/#about" },
    { name: "Contact", href: "/#contact" },
  ];

  return (
    <>
      {/* Top Banner */}
      <div className="bg-[linear-gradient(90deg,#dc2626_0%,#dc2626_70%,#ea580c_100%)] text-white text-[12px] md:text-sm font-black py-2.5 md:py-3 overflow-hidden shadow-inner">
        <div className="w-full mx-auto px-2 flex items-center justify-center gap-1.5 md:gap-2 max-w-7xl">
          <svg className="w-3.5 h-3.5 md:w-4 md:h-4 text-orange-300 fill-current shrink-0" viewBox="0 0 24 24">
            <path d="M19.333 7.828a2.593 2.593 0 0 1-1.688.625h-1.428V4.896a2.6 2.6 0 0 1 1.688.625A2.585 2.585 0 0 1 20 7.35a2.585 2.585 0 0 1-.667 1.833V7.828zm-5.428-3.14a8.47 8.47 0 0 0-4.095 1.054A8.536 8.536 0 0 0 7.57 7.57c-.742.666-1.748 1.054-2.856 1.054a1.328 1.328 0 0 1-1.334-1.325c0-.73.59-1.325 1.334-1.325h1.168a.715.715 0 0 0 .713-.711.715.715 0 0 0-.713-.711H4.714C3.217 4.552 2 5.766 2 7.26c0 1.494 1.217 2.708 2.714 2.708h2.856c1.108 0 2.114.388 2.856 1.053A8.535 8.535 0 0 0 12.8 12.92a8.47 8.47 0 0 0 4.095 1.054h.476v5.333c0 .393-.32.711-.714.711h-1.428a.715.715 0 0 0-.714.71.715.715 0 0 0 .714.711h1.428c1.18 0 2.143-.96 2.143-2.133v-5.333h.476a3.99 3.99 0 0 0 2.62-1.025A4.015 4.015 0 0 0 22 10.04a4.015 4.015 0 0 0-1.095-2.805A3.99 3.99 0 0 0 18.286 6.21h-.476V4.688zm.476 11.2h-.476v-4h.476v4z" />
          </svg>
          <div className="relative h-[18px] w-full max-w-[280px] sm:max-w-md md:max-w-lg lg:max-w-xl overflow-hidden flex items-center justify-center">
            {bannerMessages.map((msg, idx) => (
              <div 
                key={idx}
                className={`absolute w-full text-center tracking-wide md:tracking-widest uppercase transition-all duration-700 ease-in-out ${
                  idx === bannerIndex 
                    ? 'translate-y-0 opacity-100' 
                    : (idx === bannerIndex - 1 || (bannerIndex === 0 && idx === bannerMessages.length - 1))
                      ? 'translate-y-full opacity-0'
                      : '-translate-y-full opacity-0'
                }`}
              >
                {msg}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Sticky Wrapper for Phone Layer + Main Header */}
      <div className={`sticky top-0 w-full z-50 transition-all duration-300 ease-in-out flex flex-col ${isScrolled ? "shadow-md" : ""}`}>
        
        {/* Contact/Phone Numbers Layer */}
          
          {/* Desktop View (Static) */}
          <div className="hidden md:block bg-gray-100 border-b border-gray-200 py-2">
            <div className="flex items-center justify-center gap-10 max-w-7xl mx-auto">
              <a href="tel:+919042849344" className="flex items-center gap-2 group text-gray-800 hover:text-[#dc2626] transition-colors">
                <div className="bg-[#dc2626]/10 p-1.5 rounded-full group-hover:bg-[#dc2626] transition-colors">
                  <PhoneCall className="w-4 h-4 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                </div>
                <span className="text-sm font-bold tracking-wide">+91 90428 49344</span>
              </a>
              <a href="tel:+916383511818" className="flex items-center gap-2 group text-gray-800 hover:text-[#dc2626] transition-colors">
                <div className="bg-[#dc2626]/10 p-1.5 rounded-full group-hover:bg-[#dc2626] transition-colors">
                  <PhoneCall className="w-4 h-4 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                </div>
                <span className="text-sm font-bold tracking-wide">+91 63835 11818</span>
              </a>
              <a href="tel:+919344745092" className="flex items-center gap-2 group text-gray-800 hover:text-[#dc2626] transition-colors">
                <div className="bg-[#dc2626]/10 p-1.5 rounded-full group-hover:bg-[#dc2626] transition-colors">
                  <PhoneCall className="w-4 h-4 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                </div>
                <span className="text-sm font-bold tracking-wide">+91 93447 45092</span>
              </a>
            </div>
          </div>

          {/* Mobile View (Marquee) */}
          <div className="md:hidden bg-gray-100 border-b border-gray-200 py-1.5 overflow-hidden w-full relative">
            <div className="flex w-max animate-[marquee_25s_linear_infinite] hover:[animation-play-state:paused] active:[animation-play-state:paused]">
              {/* Duplicate the items to create a seamless infinite marquee */}
              {[...Array(4)].map((_, i) => (
                <div key={i} className="flex items-center gap-6 px-3">
                  <a href="tel:+919042849344" className="flex items-center gap-1.5 group text-gray-800 hover:text-[#dc2626] transition-colors">
                    <div className="bg-[#dc2626]/10 p-1 rounded-full group-hover:bg-[#dc2626] transition-colors">
                      <PhoneCall className="w-3 h-3 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                    </div>
                    <span className="text-[10px] sm:text-xs font-bold tracking-wide">+91 90428 49344</span>
                  </a>
                  <a href="tel:+916383511818" className="flex items-center gap-1.5 group text-gray-800 hover:text-[#dc2626] transition-colors">
                    <div className="bg-[#dc2626]/10 p-1 rounded-full group-hover:bg-[#dc2626] transition-colors">
                      <PhoneCall className="w-3 h-3 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                    </div>
                    <span className="text-[10px] sm:text-xs font-bold tracking-wide">+91 63835 11818</span>
                  </a>
                  <a href="tel:+919344745092" className="flex items-center gap-1.5 group text-gray-800 hover:text-[#dc2626] transition-colors">
                    <div className="bg-[#dc2626]/10 p-1 rounded-full group-hover:bg-[#dc2626] transition-colors">
                      <PhoneCall className="w-3 h-3 text-[#dc2626] group-hover:text-white animate-[wiggle_2s_infinite]" />
                    </div>
                    <span className="text-[10px] sm:text-xs font-bold tracking-wide">+91 93447 45092</span>
                  </a>
                </div>
              ))}
            </div>
          </div>
          <style dangerouslySetInnerHTML={{__html: `
            @keyframes marquee {
              0% { transform: translateX(0); }
              100% { transform: translateX(-50%); }
            }
          `}} />
  
        <header className={`w-full bg-white transition-all duration-300 ease-in-out ${
          isScrolled ? "shadow-md py-1" : "py-1.5 border-b border-gray-100"
        }`}
      >
        <div className="w-full mx-auto px-1 sm:px-4 md:px-8 max-w-7xl">
          <div className="flex items-center justify-between">
            
            {/* Logo */}
            <Link href="/" className="flex items-center group shrink-0">
              <div className="relative h-9 w-40 md:h-12 md:w-56 transition-transform duration-300">
                <Image 
                  src="/images/sky-crackers-logo.png" 
                  alt={settings?.siteName || "Sky Crackers Logo"} 
                  fill 
                  className="object-contain" 
                  priority 
                />
              </div>
            </Link>

            {/* Desktop Navigation */}
            <nav className="hidden lg:flex items-center gap-8 mx-6">
              {navLinks.map((link) => {
                const isActive = pathname === link.href || (pathname.startsWith('/shop') && link.href === '/shop');
                return (
                  <Link
                    key={link.name}
                    href={link.href}
                    className={`relative text-sm font-bold transition-colors duration-200 flex items-center ${
                      isActive 
                        ? "text-primary border-b-2 border-primary pb-1" 
                        : "text-gray-800 hover:text-primary pb-1"
                    }`}
                  >
                    {link.name}
                  </Link>
                );
              })}
              <a href={settings?.priceListUrl || "#"} target={settings?.priceListUrl ? "_blank" : "_self"} rel="noreferrer" className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-red-500 hover:bg-red-600 text-white text-[11px] uppercase tracking-wider font-bold transition-colors shadow-sm whitespace-nowrap ml-2">
                <FileText className="h-3.5 w-3.5" />
                Download Price List
              </a>
            </nav>

            {/* Right Actions */}
              <div className="flex items-center gap-3 md:gap-4 shrink-0">
                
                {/* Mobile Order Tracking Icon */}
                <Link 
                  href="/track-order" 
                  className="lg:hidden p-2 flex items-center justify-center transition-transform hover:scale-110"
                  aria-label="Track Order"
                >
                  <Image 
                    src="/track-icon.png" 
                    alt="Track Order" 
                    width={22} 
                    height={22} 
                    className="object-contain filter grayscale brightness-0 opacity-80" 
                  />
                </Link>

                {/* Quick Order Button */}
              <Link href="/shop" className="hidden sm:flex items-center gap-2 px-4 py-2 rounded-full bg-red-500 hover:bg-red-600 text-white text-sm font-bold transition-colors shadow-sm">
                <ShoppingCart className="h-4 w-4" />
                Quick Order
              </Link>

              

              {/* Cart Toggle */}
              <button 
                onClick={() => setCartOpen(true)}
                className="relative p-2 text-gray-800 hover:text-primary transition-colors group"
                aria-label="Open Cart"
              >
                <ShoppingCart className="h-6 w-6 group-hover:scale-110 transition-transform" />
                {mounted && cartItemsCount > 0 && (
                  <span className="absolute -top-1 -right-1 h-5 w-5 rounded-full bg-primary text-[10px] font-bold text-white flex items-center justify-center shadow-sm">
                    {cartItemsCount}
                  </span>
                )}
              </button>

              {/* Mobile Menu Toggle */}
              <button
                className="lg:hidden p-2 text-gray-800 hover:text-primary transition-colors"
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                aria-label="Toggle Menu"
              >
                {mobileMenuOpen ? <X className="h-7 w-7" /> : <Menu className="h-7 w-7" />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        <div className={`lg:hidden absolute top-full left-0 w-full bg-white border-b border-gray-100 shadow-xl transition-all duration-300 ease-in-out ${mobileMenuOpen ? 'max-h-[calc(100vh-80px)] overflow-y-auto opacity-100' : 'max-h-0 overflow-hidden opacity-0'}`}>
          <div className="flex flex-col p-4 gap-2">
            {navLinks.map((link) => (
              <Link
                key={link.name}
                href={link.href}
                className={`text-sm font-bold uppercase transition-colors duration-200 py-3 border-b border-gray-50 ${
                  pathname === link.href ? "text-primary" : "text-gray-700"
                }`}
                onClick={() => setMobileMenuOpen(false)}
              >
                {link.name}
              </Link>
            ))}
            <div className="pt-4 flex flex-col gap-3">
              <a href={`tel:${settings?.primaryPhone || "+919042849344"}`} className="flex items-center justify-center gap-2 py-2 rounded-lg bg-gray-50 text-gray-800 font-bold text-sm">
                <PhoneCall className="h-4 w-4 text-red-500"/> Call {settings?.primaryPhone || "+91 9042849344"}
              </a>
              <Link href="/shop" onClick={() => setMobileMenuOpen(false)} className="flex items-center justify-center gap-2 py-2 rounded-lg bg-red-500 text-white font-bold text-sm">
                <ShoppingCart className="h-4 w-4" /> Quick Order
              </Link>
              <a href={settings?.priceListUrl || "#"} target={settings?.priceListUrl ? "_blank" : "_self"} rel="noreferrer" onClick={() => setMobileMenuOpen(false)} className="flex items-center justify-center gap-2 py-2 rounded-lg bg-red-500 hover:bg-red-600 text-white font-bold text-sm">
                <FileText className="h-4 w-4" /> Download Price List
              </a>
            </div>
          </div>
        </div>
      </header>
      </div>
      <CartDrawer isOpen={cartOpen} onClose={() => setCartOpen(false)} />
    </>
  );
}
